msg.payload = {
    status: "success",
    message: "Xin chào từ Backend Node-RED!",
    time: new Date().toLocaleTimeString('vi-VN')
};
return msg;

// Thuật toán giả lập xử lý và phân loại dữ liệu sinh viên
const listSV = [
    { msv: "K235480106080", name: "Trần Hoàng Xuân Vũ", score: 9.2 },
    { msv: "K235480106081", name: "Nguyen Van A", score: 8.7 },
    { msv: "K235480106082", name: "Le Thi B", score: 7.5 },
    { msv: "K235480106083", name: "Tran Van C", score: 6.8 }
];

// Thuật toán tính toán xếp loại dựa trên điểm số
const processedList = listSV.map(sv => {
    let rank = "Trung bình";
    if (sv.score >= 9.0) rank = "Xuất sắc";
    else if (sv.score >= 8.0) rank = "Giỏi";
    else if (sv.score >= 7.0) rank = "Khá";

    return {
        msv: sv.msv,
        name: sv.name,
        score: sv.score,
        status: rank
    };
});

// Trả về định dạng JSON đúng theo yêu cầu đề bài
msg.payload = {
    ok: 1,
    msg: "Thành công - Lấy danh sách sinh viên TNUT",
    total: processedList.length,
    dssv: processedList
};

return msg;
